function icon(n){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.book}"/></svg>`}
const logo=`<svg class="brand-logo" viewBox="0 0 60 65" fill="none" aria-hidden="true"><path d="M30 3C27 13 7 13 7 30v26h46V30C53 13 33 13 30 3Z" stroke="currentColor" stroke-width="1.3"/><path d="M30 12C25 20 13 20 13 32v18h34V32c0-12-12-12-17-20Z" stroke="#b7a676"/><path d="M30 33c-5-4-11-3-13-2v16c5-1 9 0 13 3 4-3 8-4 13-3V31c-2-1-8-2-13 2Zm0 0v17M23 59h14" stroke="currentColor" stroke-width="1.5"/><path d="m30 20 2 4-2 4-2-4Z" fill="#b7a676"/></svg>`;
const brand=`<div class="brand">${logo}<div><b>معهد قالون</b><small>لتحفيظ القرآن الكريم</small></div></div>`;
let demoMode=true;
const store={get(k){try{return localStorage.getItem(k)}catch(e){return this[k.replace('qalun_','_mem_')]}},set(k,v){try{localStorage.setItem(k,v)}catch(e){this[k.replace('qalun_','_mem_')]=v}},del(k){try{localStorage.removeItem(k)}catch(e){delete this[k.replace('qalun_','_mem_')]}}};
let user=null,csrf='',token=store.get('qalun_token')||'',meta={};
function setToken(t,c){token=t;csrf=c||'';if(t){store.set('qalun_token',t);if(c)store.set('qalun_csrf',c)}else{store.del('qalun_token');store.del('qalun_csrf')}token=t||''}
let currentPage='dashboard',studentList=[],currentRecords=[],profileData=null,profileTab='overview',profileId=null,filterTimer,renderToken=0;
const roleNames={admin:'مدير المعهد',teacher:'معلم',agent:'وكيل متابعة',accountant:'محاسب'},statusNames={active:'نشط',paused:'موقوف',graduated:'متخرج',present:'حاضر',absent:'غائب',late:'متأخر',excused:'غياب بعذر'};
const titles={dashboard:'نظرة عامة',students:'إدارة الطلاب',teachers:'المعلمون',agents:'الوكلاء',accounts:'الحسابات والصلاحيات',circles:'الحلقات القرآنية',attendance:'الحضور والغياب',progress:'الحفظ والمراجعة',monthly:'الاختبارات الشهرية',quarterly:'الامتحانات الدورية',finance:'الرسوم والمدفوعات',reports:'التقارير والإحصائيات',notifications:'التنبيهات',settings:'إعدادات المعهد',schedules:'المواعيد القادمة',profile:'ملف الطالب'};
const permNames={attendance:'تسجيل الحضور',progress:'تسجيل الحفظ والمراجعة',monthly:'الاختبارات الشهرية',quarterly:'الامتحانات الدورية',reports:'استخراج التقارير',finance:'الرسوم والمدفوعات',read_all:'عرض طلاب جميع المعلمين / الوكلاء'};
const fmt=n=>Number(n||0).toLocaleString('en-US',{maximumFractionDigits:2}),num=n=>Number(n||0).toLocaleString('ar'),currency=()=>esc(meta.settings?.currency||'MRU');
const has=p=>user?.role==='admin'||user?.permissions.includes(p);
const canFinanceWrite=()=>['admin','accountant'].includes(user?.role)&&has('finance');
const initials=n=>String(n||'').split(' ').slice(0,2).map(x=>x[0]).join(' ');
function badge(s){const colors={paused:'gray',graduated:'blue',absent:'red',late:'orange',excused:'blue'};return `<span class="badge ${colors[s]||''}">${esc(statusNames[s]||s)}</span>`}
function gradeName(n){return n>=90?'ممتاز':n>=80?'جيد جدًا':n>=70?'جيد':n>=60?'مقبول':'يحتاج إلى دعم'}
function money(n){return `${fmt(n)} <small style="display:inline;font-size:9px;color:#9ba793">${currency()}</small>`}
function avatar(s,i=0){return `<span class="avatar ${['','gold','blue','pink'][i%4]}">${esc(initials(s.name))}</span>`}
function toast(message,error=false){let t=$('#toast');t.textContent=message;t.className='show'+(error?' error':'');clearTimeout(t.timer);t.timer=setTimeout(()=>t.className='',4500)}
async function api(url,method='GET',body){let h={'Content-Type':'application/json'};if(token){h['X-Auth-Token']=token;h['X-CSRF-Token']=csrf||store.get('qalun_csrf')||''}let r=await fetch('/api'+url,{method,headers:h,body:body===undefined?undefined:JSON.stringify(body),credentials:'same-origin'});let data;try{data=await r.json()}catch{throw Error('تعذّر الاتصال بالخادم؛ حاول مجددًا')}if(!r.ok){if(r.status===401&&user){user=null;setToken('');showLogin()}throw Error(data.error||'تعذّر تنفيذ العملية')}return data}
window.addEventListener('unhandledrejection',e=>{toast(e.reason?.message||'حدث خطأ غير متوقع',true);e.preventDefault()});
function showLogin(){ $('#app').classList.add('hidden');$('#login').classList.remove('hidden');$('#login').innerHTML=`<div class="login-screen"><section class="login-art"><div>${brand}<h1>نرعى رحلة الحفظ،<br>ونصنع أثرًا يبقى.</h1><p>مساحة واحدة تجمع شؤون المعهد، وتقرّب المعلم والوكيل من رحلة كل طالب مع كتاب الله.</p><div class="bottom-note">${icon('lock')} صلاحيات دقيقة · متابعة مترابطة · إدارة واضحة</div></div></section><section class="login-form-side"><div class="login-box"><span class="mini-tag">معهد قالون لتحفيظ القرآن الكريم</span><h2>مرحبًا بعودتك</h2><p>سجّل الدخول إلى حسابك لمتابعة يومك في المعهد.</p><form id="loginForm"><div class="field"><label for="username">اسم المستخدم</label><input id="username" name="username" dir="ltr" required autocomplete="username" placeholder="اسم المستخدم"></div><div class="field"><label for="password">كلمة المرور</label><div class="pass-wrap"><input id="password" name="password" dir="ltr" type="password" required autocomplete="current-password" placeholder="أدخل كلمة المرور"><button type="button" class="pass-toggle" onclick="togglePass()" aria-label="إظهار كلمة المرور">◉</button></div></div><div id="loginError"></div><button class="btn primary" type="submit">تسجيل الدخول ${icon('arrow')}</button></form><div class="demo-accounts"><span>⚡ دخول سريع — اضغط لتعبئة الحقول وتسجيل الدخول مباشرة</span><div class="demo-buttons"><button onclick="fillDemo('admin')">المدير</button><button onclick="fillDemo('teacher')">المعلم</button><button onclick="fillDemo('agent')">الوكيل</button><button onclick="fillDemo('accountant')">المحاسب</button></div><div class="demo-pass">أو ادخل يدويًا: المستخدم <b>admin</b> وكلمة المرور <b dir="ltr" class="mono-pass">Qalun@2026!</b> <button type="button" class="btn small" onclick="copyPass()">نسخ</button><br>حسابات أخرى: teacher · agent · accountant (كلمة المرور نفسها)</div></div></div></section></div>`;if(!demoMode)document.querySelector('.demo-accounts')?.remove();$('#loginForm').onsubmit=async e=>{e.preventDefault();let b=e.target.querySelector('button');b.disabled=true;b.textContent='جارٍ التحقق…';try{let d=await api('/login','POST',Object.fromEntries(new FormData(e.target)));user=d.user;csrf=d.csrf;setToken(d.token,d.csrf);await boot()}catch(err){$('#loginError').innerHTML=`<div class="form-error">${esc(err.message)}</div>`}finally{b.disabled=false;b.innerHTML='تسجيل الدخول '+icon('arrow')}}}
function fillDemo(role){$('#username').value=role;$('#password').value='Qalun@2026!';$('#loginError').innerHTML='';if($('#loginForm').requestSubmit)$('#loginForm').requestSubmit();else $('#loginForm').submit()}
function togglePass(){let i=$('#password');i.type=i.type==='password'?'text':'password'}
function copyPass(){if(navigator.clipboard)navigator.clipboard.writeText('Qalun@2026!').then(()=>toast('نُسخت كلمة المرور؛ الصقها في الحقل')).catch(()=>{});else toast('انسخ يدويًا: Qalun@2026!')}
async function boot(){meta=await api('/meta');demoMode=meta.settings.demo==='1';$('.demo-strip').classList.toggle('hidden',!demoMode);$('#login').classList.add('hidden');$('#app').classList.remove('hidden');$('#userAvatar').textContent=initials(user.name);$('#userName').textContent=user.name;$('#userRole').textContent=roleNames[user.role];$('#today').textContent=new Date(meta.today+'T12:00:00').toLocaleDateString('ar',{weekday:'long',day:'numeric',month:'long',year:'numeric'});$('#bell').innerHTML=icon('bell')+'<i class="dot"></i>';renderSidebar();await route()}
function renderSidebar(){let items=[['dashboard','dashboard'],['students','students'],...(user.role==='admin'?[['teachers','teacher'],['agents','agent']]:[]),['circles','book']];let education=user.role==='accountant'?[]:[['attendance','attendance'],['progress','book'],['monthly','exam'],['quarterly','agent']];let management=[...(has('finance')?[['finance','finance']]:[]),...(has('reports')||has('finance')?[['reports','reports']]:[]),['schedules','calendar'],['notifications','bell'],...(user.role==='admin'?[['accounts','users'],['settings','settings']]:[])];let links=arr=>arr.map(([id,ic])=>`<button class="nav-item ${currentPage===id?'active':''}" onclick="navigate('${id}')" data-page="${id}">${icon(ic)}<span>${titles[id]}</span></button>`).join('');$('#sidebar').innerHTML=`<a class="sidebar-brand" href="#dashboard">${brand}</a><div class="nav-heading">الرئيسية</div>${links(items)}${education.length?'<div class="nav-heading">الشؤون التعليمية</div>'+links(education):''}<div class="nav-heading">إدارة المعهد</div>${links(management)}<div class="side-bottom"><div class="side-verse"><span class="star">✦</span><p>«خيرُكم من تعلّم القرآن وعلّمه»</p><small>بالقرآن نرتقي.. وبأخلاقه نسمو</small></div><button class="nav-item" onclick="logout()">${icon('logout')}تسجيل الخروج</button></div>`}
async function logout(){try{await api('/logout','POST',{})}catch(e){}setToken('');user=null;csrf='';location.hash='dashboard';showLogin()}
function navigate(page){document.body.classList.remove('menu-open');if(location.hash==='#'+page)route();else location.hash=page}
window.addEventListener('hashchange',()=>{if(user)route()});
async function route(){let hash=location.hash.slice(1)||'dashboard';currentPage=hash.split('/')[0];let token=++renderToken;$('#pageCrumb').textContent=titles[currentPage]||'نظرة عامة';document.querySelectorAll('.nav-item').forEach(n=>n.classList.toggle('active',n.dataset.page===currentPage));$('#content').innerHTML='<div class="loading"><div class="spinner"></div>جارٍ تحميل البيانات…</div>';try{if(currentPage==='dashboard')await dashboard();else if(currentPage==='students')await studentsPage();else if(currentPage==='profile'){profileId=Number(hash.split('/')[1]);profileTab='overview';await profilePage()}else if(['teachers','agents','accounts'].includes(currentPage))await usersPage();else if(currentPage==='circles')await circlesPage();else if(currentPage==='attendance')await attendancePage();else if(['progress','monthly','quarterly'].includes(currentPage))await recordsPage(currentPage);else if(currentPage==='finance')await financePage();else if(currentPage==='reports')await reportsPage();else if(currentPage==='notifications')await notificationsPage();else if(currentPage==='schedules')await schedulesPage();else if(currentPage==='settings')await settingsPage();else navigate('dashboard')}catch(e){if(token===renderToken)$('#content').innerHTML=`<div class="panel empty">${icon('lock')}${esc(e.message)}<br><button class="btn" onclick="navigate('dashboard')">العودة للوحة الرئيسية</button></div>`}window.scrollTo(0,0)}
function heading(title,sub,actions=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${sub}</p></div><div class="page-actions">${actions}</div></div>`}
function btn(text,action,ic='plus',primary=true){return `<button class="btn ${primary?'primary':''}" onclick="${action}">${icon(ic)}${text}</button>`}
function empty(text='لا توجد سجلات بعد. يمكنك بدء إضافة البيانات.'){return `<div class="empty">${icon('book')}${text}</div>`}
function table(headers,body){return `<div class="table-wrap"><table><thead><tr>${headers.map(x=>`<th>${x}</th>`).join('')}</tr></thead><tbody>${body}</tbody></table></div>`}
function stat(label,value,ic,color,foot,page){return `<button class="stat" onclick="navigate('${page}')"><span class="stat-top">${label}<span class="stat-icon ${color}">${icon(ic)}</span></span><strong class="stat-number">${fmt(value)}</strong><span class="stat-foot"><span>${foot}</span><em>عرض التفاصيل ↙</em></span></button>`}
async function dashboard(){let [d,ss,schedules]=await Promise.all([api('/dashboard'),api('/students'),api('/schedules')]);studentList=ss;let accountant=user.role==='accountant';let a=d.attendance||{},total=Object.values(a).reduce((v,n)=>v+n,0),present=(a.present||0)+(a.late||0),pct=total?Math.round(present/total*100):0;let upcoming=schedules.filter(s=>s.date>=meta.today);let dateRange=btn('التقارير','navigate(\'reports\')','download',false);let add=user.role==='admin'?btn('إضافة طالب','studentForm()'):'';
$('#content').innerHTML=heading('نظرة عامة','مرحبًا '+esc(user.name)+'، إليك ملخص يومك في معهد قالون.',dateRange+add)+`<section class="welcome-banner"><div><span class="welcome-tag">${user.role==='admin'?'لوحة تحكم الإدارة':roleNames[user.role]+' · بيانات ضمن صلاحياتك'}</span><h2>كلّ آية تُحفظ.. خطوة نحو النور.</h2><p>تابع رحلة طلابك، واطّلع على مستجدات المعهد من مكان واحد.<br>معًا نعتني بالحفظ، ونبني جيلًا يرتقي بالقرآن.</p></div><div class="banner-art">${icon('book')}<span class="banner-spark">✧</span></div></section><div class="stats-grid">${stat('إجمالي الطلاب',d.students,'students','','طالبًا ضمن نطاق حسابك','students')}${stat('المعلمون',d.teachers,'teacher','gold','معلمو الحلقات',user.role==='admin'?'teachers':'circles')}${stat('الوكلاء',d.agents,'agent','blue','متابعة ورعاية',user.role==='admin'?'agents':'students')}${stat('الحلقات القرآنية',d.circles,'book','purple','بيئات تعليمية متكاملة','circles')}</div>${!accountant?`<div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h3>الحضور خلال الأسبوع</h3><p>متابعة انتظام الطلاب خلال آخر ٧ أيام</p></div><div class="chart-legend"><span><i class="legend-dot"></i>حضور وتأخر</span><span><i class="legend-dot pale"></i>إجمالي المسجّل</span></div></div>${attendanceChart(d.attendance_week)}</section><section class="panel"><div class="panel-head"><div><h3>الحضور اليوم</h3><p>${esc(meta.today)} · ${num(total)} سجل حضور</p></div><button class="text-button" onclick="navigate('attendance')">${icon('arrow')}</button></div><div class="donut-content"><div class="donut" style="background:conic-gradient(#86a67c 0 ${pct}%,#e8eede ${pct}% 100%)"><div class="donut-center"><strong>${pct}<span style="font-size:17px">%</span></strong><small>نسبة الحضور*</small></div></div><div class="donut-legend"><div><span><i class="legend-dot"></i>حاضر</span><b>${num(a.present||0)}</b></div><div><span><i class="legend-dot" style="background:#d4b17a"></i>متأخر</span><b>${num(a.late||0)}</b></div><div><span><i class="legend-dot" style="background:#d2a4a0"></i>غائب</span><b>${num(a.absent||0)}</b></div><div><span><i class="legend-dot pale"></i>بعذر</span><b>${num(a.excused||0)}</b></div></div></div></section></div>`:''}${!accountant?`<div class="small-stats">${smallStat('اختبارات هذا الشهر',num(d.monthly_count))}${smallStat('متوسط الاختبارات',fmt(d.monthly_average)+'%')}${smallStat('متوسط الامتحانات',fmt(d.quarterly_average)+'%')}${smallStat('الامتحانات القادمة',num(upcoming.filter(s=>s.type==='quarterly').length))}</div>`:''}<div class="dashboard-grid"><section class="panel"><div class="panel-head"><div><h3>${d.finance?'الملخص المالي':'مستوى الأداء التعليمي'}</h3><p>${d.finance?'أرقام مباشرة من المستحقات والمدفوعات':'النتائج الفعلية المسجلة لطلابك'}</p></div><button class="text-button" onclick="navigate('${d.finance?'finance':'monthly'}')">عرض التفاصيل ←</button></div><div class="financial-grid">${d.finance?financialMini('إجمالي المحصّل',d.finance.paid)+financialMini('المتبقي',d.finance.balance)+financialMini('المتأخرات',d.finance.overdue):`<div class="financial-item"><span>الاختبارات هذا الشهر</span><strong>${num(d.monthly_count)}</strong><small>اختبار مسجّل</small></div><div class="financial-item"><span>متوسط الاختبارات</span><strong>${fmt(d.monthly_average)}%</strong><small>جميع النتائج</small></div><div class="financial-item"><span>متوسط الامتحانات</span><strong>${fmt(d.quarterly_average)}%</strong><small>جميع النتائج</small></div>`}</div></section><section class="panel"><div class="panel-head"><div><h3>المواعيد القادمة</h3><p>${num(upcoming.length)} مواعيد مجدولة</p></div><button class="text-button" onclick="navigate('schedules')">عرض الكل ←</button></div>${upcoming.slice(0,2).map(scheduleRow).join('')||empty('لا توجد مواعيد قادمة')}</section></div><section class="panel"><div class="panel-head"><div><h3>أحدث الطلاب</h3><p>لمحة عن الطلاب والحلقات والوكلاء</p></div><button class="text-button" onclick="navigate('students')">جميع الطلاب ←</button></div>${studentTable(ss.slice(0,5),true)}<div class="table-foot"><span>عرض ${num(Math.min(5,ss.length))} من ${num(ss.length)} طالبًا</span><span>تُحدّث البيانات عند فتح الصفحة</span></div></section>${!accountant?'<p class="help">* نسبة الحضور = (الحاضر + المتأخر) ÷ إجمالي سجلات اليوم، ويشمل الإجمالي الغياب بعذر. غير المسجّل لا يدخل في النسبة.</p>':''}`}
function attendanceChart(rows){if(!rows?.length)return empty('لم يُسجّل حضور بعد');let max=Math.max(...rows.map(r=>r.total),1);return `<div class="bars-chart"><div class="chart-scale"><span>${max}</span><span>${Math.round(max*.75)}</span><span>${Math.round(max*.5)}</span><span>0</span></div><div class="bars-area">${rows.map(r=>`<div class="bar-pair"><div class="bar" style="height:${r.present/max*100}%" title="${r.date}: ${r.present} حاضر ومتأخر"></div><div class="bar pale" style="height:${r.total/max*100}%" title="الإجمالي: ${r.total}"></div><span class="bar-label">${new Date(r.date+'T12:00:00').toLocaleDateString('ar',{weekday:'short'})}</span></div>`).join('')}</div></div>`}
function financialMini(label,val){return `<div class="financial-item"><span>${label}</span><strong>${fmt(val)}</strong><small>${currency()}</small></div>`}
function scheduleRow(s){let dt=new Date(s.date+'T12:00:00');return `<div class="schedule-row"><div class="date-square"><strong>${dt.getDate()}</strong><small>${dt.toLocaleDateString('ar',{month:'short'})}</small></div><div><b>${esc(s.title)}</b><p>${esc(s.circle_name||'جميع الحلقات')}</p></div><span class="badge ${s.type==='monthly'?'':'orange'}">${s.type==='monthly'?'شهري':'دوري'}</span></div>`}
function studentTable(ss,brief=false){if(!ss.length)return empty('لا يوجد طلاب مطابقون لخيارات البحث.');return table(['الطالب','الحلقة','المعلم','الوكيل','الحالة',''],ss.map((s,i)=>`<tr><td><a class="person" href="#profile/${s.id}">${avatar(s,i)}<span><strong>${esc(s.name)}</strong><small dir="ltr" style="text-align:right">${esc(s.code)}</small></span></a></td><td>${esc(s.circle_name||'غير محددة')}<small>${esc(s.level)}</small></td><td>${esc(s.teacher_name||'—')}</td><td>${esc(s.agent_name||'—')}</td><td>${badge(s.status)}</td><td><button class="text-button" onclick="navigate('profile/${s.id}')">عرض الملف ←</button>${!brief&&user.role==='admin'?` <button class="icon-button" onclick="studentForm(${s.id})" aria-label="تعديل">${icon('edit')}</button>`:''}</td></tr>`).join(''))}
function options(arr,valueKey='id',labelKey='name',selected=''){return arr.map(x=>`<option value="${esc(x[valueKey])}" ${String(x[valueKey])===String(selected)?'selected':''}>${esc(x[labelKey])}</option>`).join('')}
async function studentsPage(){studentList=await api('/students');$('#content').innerHTML=heading('إدارة الطلاب','كل طالب، وقصة حفظ، وملف يجمع رحلة كاملة.',(user.role==='admin'?btn('إضافة طالب جديد','studentForm()')+btn('استيراد CSV','importModal()','plus',false):'')+btn('تصدير القائمة','exportStudents()','download',false))+`<section class="panel"><div class="filter-bar"><input class="search" id="studentSearch" placeholder="ابحث بالاسم أو الرقم التعريفي…" aria-label="البحث عن طالب" oninput="filterStudents()"><select id="filterCircle" onchange="filterStudents()" aria-label="الحلقة"><option value="">جميع الحلقات</option>${options(meta.circles)}</select>${user.role==='admin'?`<select id="filterTeacher" onchange="filterStudents()" aria-label="المعلم"><option value="">جميع المعلمين</option>${options(meta.users.filter(u=>u.role==='teacher'))}</select><select id="filterAgent" onchange="filterStudents()" aria-label="الوكيل"><option value="">جميع الوكلاء</option>${options(meta.users.filter(u=>u.role==='agent'))}</select>`:''}<select id="filterLevel" onchange="filterStudents()" aria-label="المستوى"><option value="">جميع المستويات</option>${['مبتدئ','متوسط','متقدم'].map(x=>`<option>${x}</option>`).join('')}</select><select id="filterStatus" onchange="filterStudents()" aria-label="الحالة"><option value="">جميع الحالات</option><option value="active">نشط</option><option value="paused">موقوف</option><option value="graduated">متخرج</option></select><span class="filter-count" id="studentCount">${num(studentList.length)} طالبًا</span></div><div id="studentsTable">${studentTable(studentList)}</div></section>`}
let searchVersion=0;
function filterStudents(){clearTimeout(filterTimer);filterTimer=setTimeout(async()=>{let v=++searchVersion;let q=new URLSearchParams();for(let [id,k] of [['studentSearch','q'],['filterCircle','circle'],['filterTeacher','teacher'],['filterAgent','agent'],['filterLevel','level'],['filterStatus','status']]){if($('#'+id)?.value)q.set(k,$('#'+id).value)}let result=await api('/students?'+q);if(v!==searchVersion||currentPage!=='students')return;studentList=result;$('#studentsTable').innerHTML=studentTable(studentList);$('#studentCount').textContent=num(studentList.length)+' طالبًا'},200)}
let lastFocus;
function openModal(html,wide=false){lastFocus=document.activeElement;$('#modalBody').innerHTML=html;$('.modal').classList.toggle('wide',wide);$('#modalBackdrop').classList.remove('hidden');document.body.style.overflow='hidden';$('.modal-close').focus()}
function closeModal(){ $('#modalBackdrop').classList.add('hidden');document.body.style.overflow='';lastFocus?.focus() }
$('#modalBackdrop').addEventListener('click',e=>{if(e.target.id==='modalBackdrop')closeModal()});document.addEventListener('keydown',e=>{if($('#modalBackdrop').classList.contains('hidden'))return;if(e.key==='Escape')closeModal();if(e.key==='Tab'){let ns=[...$('.modal').querySelectorAll('button,input,select,textarea,a[href]')].filter(n=>!n.disabled&&n.offsetParent!==null),first=ns[0],last=ns[ns.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus()}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus()}}});
function field(name,label,type='text',value='',extra='',full=false){return `<div class="field ${full?'full':''}"><label for="f-${name}">${label}</label>${type==='textarea'?`<textarea id="f-${name}" name="${name}" ${extra}>${esc(value)}</textarea>`:`<input id="f-${name}" name="${name}" type="${type}" value="${esc(value)}" ${extra}>`}</div>`}
function selectField(name,label,opts,full=false){return `<div class="field ${full?'full':''}"><label for="f-${name}">${label}</label><select name="${name}" id="f-${name}">${opts}</select></div>`}
function formModal(title,sub,fields,onSubmit,wide=false){openModal(`<h2 id="modalTitle">${title}</h2><p class="modal-description">${sub}</p><form id="editForm"><div class="form-grid">${fields}</div><div id="formError"></div><div class="form-actions"><button type="button" class="btn" onclick="closeModal()">إلغاء</button><button type="submit" class="btn primary">${icon('check')}حفظ البيانات</button></div></form>`,wide);$('#editForm').onsubmit=async e=>{e.preventDefault();let b=e.target.querySelector('[type=submit]');b.disabled=true;$('#formError').innerHTML='';try{await onSubmit(Object.fromEntries(new FormData(e.target)),e.target);closeModal();toast('تم حفظ البيانات بنجاح');meta=await api('/meta');await refreshPage()}catch(err){$('#formError').innerHTML=`<div class="form-error">${esc(err.message)}</div>`}finally{b.disabled=false}}}
async function refreshPage(){if(currentPage==='profile')await profilePage();else await route()}
async function studentForm(id){let s=id?(await api('/students/'+id)).student:{status:'active',registered:meta.today};let fields=field('name','الاسم الكامل *','text',s.name,'required maxlength="120"')+field('birth_date','تاريخ الميلاد','date',s.birth_date,`max="${meta.today}"`)+field('phone','هاتف الطالب','tel',s.phone)+field('registered','تاريخ التسجيل *','date',s.registered,'required')+field('guardian','اسم ولي الأمر','text',s.guardian)+field('guardian_phone','هاتف ولي الأمر','tel',s.guardian_phone)+selectField('circle_id','الحلقة (المعلم مرتبط بها)',`<option value="">غير محددة</option>`+options(meta.circles,'id','name',s.circle_id))+selectField('agent_id','الوكيل المسؤول',`<option value="">غير محدد</option>`+options(meta.users.filter(u=>u.role==='agent'),'id','name',s.agent_id))+selectField('level','المستوى',options(['مبتدئ','متوسط','متقدم'].map(x=>({id:x,name:x})),'id','name',s.level))+selectField('status','حالة الطالب',options(['active','paused','graduated'].map(x=>({id:x,name:statusNames[x]})),'id','name',s.status))+field('photo','صورة الطالب (JPEG / PNG / WebP، حتى 500 كيلوبايت)','file','','accept="image/jpeg,image/png,image/webp"',true)+field('notes','ملاحظات الإدارة','textarea',s.notes,'maxlength="3000"',true);formModal(id?'تعديل ملف الطالب':'إضافة طالب جديد',id?esc(s.code)+' · ينتقل نطاق الوصول تلقائيًا عند تغيير الحلقة أو الوكيل.':'يُنشأ الرقم التعريفي تلقائيًا، وتُربط جميع سجلات الطالب بهذا الملف.',fields,async(d,f)=>{let file=f.elements.photo.files[0];d.photo=s.photo||'';if(file){if(file.size>500000)throw Error('حجم الصورة يجب ألا يتجاوز 500 كيلوبايت');d.photo=await new Promise((resolve,reject)=>{let r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)})}await api('/students'+(id?'/'+id:''),id?'PUT':'POST',d)})}
async function removeStudent(id){if(!confirm('هل تريد حذف الطالب وجميع سجلاته التعليمية نهائيًا؟ يُمنع الحذف عند وجود قيود مالية.'))return;await api('/students/'+id,'DELETE');toast('تم حذف الطالب');navigate('students')}
function exportCSV(name,headers,rows){let cell=v=>{let x=String(v??'');if(/^[=+@\-\t\r]/.test(x))x="'"+x;return '"'+x.replace(/"/g,'""')+'"'};let csv='\uFEFF'+[headers,...rows].map(r=>r.map(cell).join(',')).join('\r\n');let a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download=name+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function exportStudents(){exportCSV('طلاب-معهد-قالون',['الرقم','الاسم','الحلقة','المعلم','الوكيل','المستوى','الحالة'],studentList.map(s=>[s.code,s.name,s.circle_name,s.teacher_name,s.agent_name,s.level,statusNames[s.status]]))}
async function profilePage(){profileData=await api('/students/'+profileId);let s=profileData.student;$('#content').innerHTML=heading('ملف الطالب','البيانات والمتابعة والنتائج في مكان واحد.',btn('قائمة الطلاب','navigate(\'students\')','arrow',false))+`<section class="profile-head"><span class="avatar large">${s.photo?`<img src="${esc(s.photo)}" alt="صورة الطالب">`:esc(initials(s.name))}</span><div><h2>${esc(s.name)} ${badge(s.status)}</h2><p>${esc(s.code)} <span style="margin:0 10px;color:#d0d9c5">|</span>${esc(s.circle_name||'دون حلقة')} <span style="margin:0 10px;color:#d0d9c5">|</span>${esc(s.level||'غير محدد')}</p></div><div class="page-actions">${has('reports')||has('finance')?btn('التقرير الشامل',`reportModal(${s.id})`,'reports',false):''}${user.role==='admin'?btn('تعديل البيانات',`studentForm(${s.id})`,'edit'):''}</div></section><div class="tabs">${[['overview','نظرة عامة'],...(user.role!=='accountant'?[['attendance','الحضور والغياب'],['progress','الحفظ والمراجعة'],['monthly','الاختبارات الشهرية'],['quarterly','الامتحانات الدورية']]:[]),...(has('finance')?[['finance','الرسوم والمدفوعات']]:[]),...(user.role!=='accountant'?[['history','سجل التطور']]:[]),...(has('reports')||has('finance')?[['archives','التقارير السابقة']]:[])].map(([id,n])=>`<button class="tab ${profileTab===id?'active':''}" onclick="changeProfileTab('${id}')">${n}</button>`).join('')}</div><div id="profileContent"></div>`;renderProfileTab()}
function changeProfileTab(tab){profileTab=tab;document.querySelectorAll('.tab').forEach(n=>n.classList.toggle('active',n.getAttribute('onclick').includes("'"+tab+"'")));renderProfileTab()}
function attendanceStats(records){let n={present:0,absent:0,late:0,excused:0};records.forEach(r=>n[r.status]++);n.rate=records.length?Math.round((n.present+n.late)/records.length*100):0;return n}
function info(label,value){return `<div class="info-item"><label>${label}</label><b>${esc(value||'—')}</b></div>`}
function smallStat(label,val){return `<div class="small-stat"><label>${label}</label><b>${val}</b></div>`}
function renderProfileTab(){let d=profileData,s=d.student,r=d.records,target=$('#profileContent');if(profileTab==='overview'){let a=attendanceStats(r.attendance||[]),p=r.progress?.[0],m=r.monthly?.[0];target.innerHTML=`${user.role!=='accountant'?`<div class="small-stats">${smallStat('نسبة الحضور',a.rate+'%')}${smallStat('آخر مستوى إتقان',p?fmt(p.mastery)+'%':'—')}${smallStat('آخر اختبار شهري',m?fmt(m.grade)+'/100':'—')}${smallStat('سجلات الحفظ والمراجعة',num(r.progress?.length||0))}</div>`:''}<section class="panel"><div class="panel-head"><h3>البيانات الشخصية والتعليمية</h3></div><div class="profile-info">${info('الاسم الكامل',s.name)+info('الرقم التعريفي',s.code)+info('تاريخ الميلاد',s.birth_date)+info('هاتف الطالب',s.phone)+info('ولي الأمر',s.guardian)+info('هاتف ولي الأمر',s.guardian_phone)+info('تاريخ التسجيل',s.registered)+info('الحلقة',s.circle_name)+info('المعلم المسؤول',s.teacher_name)+info('الوكيل المسؤول',s.agent_name)+info('المستوى',s.level)+info('الحالة',statusNames[s.status])}${user.role!=='accountant'?info('ملاحظات الإدارة',s.notes):''}</div></section>${user.role==='admin'?`<div style="margin-top:20px"><button class="btn danger small" onclick="removeStudent(${s.id})">${icon('trash')} حذف الطالب</button><span class="help" style="margin-right:12px">يمكن إيقاف الطالب من تعديل البيانات بدلًا من حذف سجلاته.</span></div>`:''}`}
else if(profileTab==='archives'){target.innerHTML='<section class="panel"><div class="panel-head"><h3>التقارير المحفوظة</h3><button class="btn small" onclick="reportModal('+s.id+')">إنشاء تقرير</button></div><div id="archiveList"></div></section>';loadArchives(s.id)}
else if(profileTab==='history'){let m=r.monthly||[],last=m[0],old=m[m.length-1],diff=last&&old?last.grade-old.grade:null;target.innerHTML=`<div class="small-stats">${smallStat('أحدث اختبار',last?fmt(last.grade):'—')}${smallStat('أقدم اختبار',old?fmt(old.grade):'—')}${smallStat('فرق الدرجات',diff===null?'—':(diff>0?'+':'')+fmt(diff))}${smallStat('اختبارات مسجّلة',num(m.length))}</div><section class="panel"><div class="panel-head"><h3>سجل النشاط والتحديثات</h3></div><div class="timeline">${d.events.map(e=>`<div class="timeline-row"><b>${esc(e.action)}</b><small>${esc(e.date.replace('T',' · '))} — ${esc(e.actor||'الإدارة')}</small></div>`).join('')||empty('لا توجد تحديثات مسجّلة')}</div></section>`}
else if(profileTab==='finance'){target.innerHTML=`<div class="small-stats">${smallStat('المستحقات',money(d.finance.charged))}${smallStat('المدفوع',money(d.finance.paid))}${smallStat('المتبقي',money(d.finance.balance))}${smallStat('المتأخرات',money(d.finance.overdue))}</div><div class="page-heading"><h3>السجل المالي</h3><div class="page-actions">${canFinanceWrite()?btn('إثبات رسوم',`recordForm('charges',${s.id})`,'plus',false)+btn('تسجيل دفعة',`recordForm('payments',${s.id})`,'plus'):''}</div></div><section class="panel"><div class="panel-head"><h3>المدفوعات</h3></div>${recordTable('payments',r.payments||[],true)}</section><section class="panel" style="margin-top:20px"><div class="panel-head"><h3>المستحقات</h3></div>${recordTable('charges',r.charges||[],true)}</section>`}
else {let kind=profileTab,can=has(kind);target.innerHTML=`${kind==='attendance'?(()=>{let a=attendanceStats(r.attendance);return `<div class="small-stats">${smallStat('حاضر',num(a.present))}${smallStat('غائب',num(a.absent))}${smallStat('متأخر',num(a.late))}${smallStat('غياب بعذر',num(a.excused))}</div>`})():''}<section class="panel"><div class="panel-head"><div><h3>${titles[kind]}</h3><p>جميع السجلات مرتبة من الأحدث إلى الأقدم</p></div>${can?btn('إضافة سجل',`recordForm('${kind}',${s.id})`):''}</div>${recordTable(kind,r[kind]||[],true)}</section>`}}
async function usersPage(){let us=await api('/users'),role=currentPage==='teachers'?'teacher':currentPage==='agents'?'agent':null;window.userRows=us.filter(u=>!role||u.role===role);let label=role==='teacher'?'معلم':role==='agent'?'وكيل':'حساب';$('#content').innerHTML=heading(titles[currentPage],'حسابات مستقلة وصلاحيات تُطبّق على الخادم، وليست مجرد أزرار مخفية.',btn('إضافة '+label,`userForm(null,'${role||'teacher'}')`))+`<section class="panel"><div class="panel-head"><h3>${num(window.userRows.length)} ${role?'حسابًا':'مستخدمًا'}</h3><span class="help">كلمات المرور مخزّنة بصيغة مجزّأة</span></div>${table(['الاسم','اسم المستخدم','الدور','الهاتف','التخصص','حالة الحساب',''],window.userRows.map((u,i)=>`<tr><td><span class="person">${avatar(u,i)}<strong>${esc(u.name)}</strong></span></td><td dir="ltr" style="text-align:right">${esc(u.username)}</td><td>${roleNames[u.role]}</td><td>${esc(u.phone||'—')}</td><td>${esc(u.specialty||'—')}</td><td>${badge(u.status)}</td><td><button class="btn small" onclick="userForm(${u.id},'${u.role}')">${icon('edit')}الحساب والصلاحيات</button></td></tr>`).join(''))}</section>`}
function userForm(id,role){let u=id?window.userRows.find(x=>x.id===id):{role,status:'active',permissions:({teacher:['attendance','progress','monthly','quarterly','reports'],agent:['reports'],accountant:['finance'],admin:['all']})[role]};let html=field('name','الاسم الكامل *','text',u.name,'required')+field('username','اسم المستخدم (لاتيني) *','text',u.username,'required pattern="[a-zA-Z0-9_.-]{3,40}" dir="ltr" autocomplete="off"')+field('password',id?'كلمة مرور جديدة (اتركها فارغة للإبقاء)':'كلمة المرور *','password','','minlength="10" '+(id?'':'required')+' autocomplete="new-password"')+selectField('role','دور الحساب',options(Object.entries(roleNames).map(([id,name])=>({id,name})),'id','name',u.role))+field('phone','رقم الهاتف','tel',u.phone)+field('specialty','التخصص','text',u.specialty)+selectField('status','حالة الحساب',options([{id:'active',name:'نشط'},{id:'paused',name:'موقوف'}],'id','name',u.status))+`<div class="field full"><label>صلاحيات الحساب</label><div id="permissions"></div></div>`;formModal(id?'تعديل الحساب والصلاحيات':'إضافة حساب جديد','الطلاب مرتبطون بالمعلم عبر الحلقات، وبالوكيل عبر ملف الطالب. دور الحساب القائم لا يتغير.',html,async(d,f)=>{d.permissions=[...f.querySelectorAll('[name=permission]:checked')].map(x=>x.value);await api('/users'+(id?'/'+id:''),id?'PUT':'POST',d)});let renderPerms=()=>{let rr=$('#f-role').value,allowed=({admin:[],teacher:['attendance','progress','monthly','quarterly','reports','read_all'],agent:['reports','finance'],accountant:['finance']})[rr];$('#permissions').innerHTML=rr==='admin'?'<div class="notice">للمدير صلاحية كاملة. لا تمنح هذا الدور إلا لمن تثق به.</div>':`<div class="permission-list">${allowed.map(p=>`<label class="check-label"><input type="checkbox" name="permission" value="${p}" ${u.permissions.includes(p)?'checked':''}>${permNames[p]}</label>`).join('')}</div><p class="help">«عرض جميع الطلاب» استثناء صريح من عزل الحساب. اتركه غير مفعّل للحفاظ على نطاق الطلاب المسندين فقط.</p>`};$('#f-role').onchange=renderPerms;if(id)$('#f-role').setAttribute('aria-readonly','true');renderPerms()}
async function circlesPage(){let cs=await api('/circles');window.circleRows=cs;$('#content').innerHTML=heading('الحلقات القرآنية','حلقات متكاملة، ومعلمون يرافقون رحلة التعلّم.',user.role==='admin'?btn('إضافة حلقة','circleForm()'):'')+`<div class="section-grid">${cs.map(c=>`<article class="circle-card"><div style="display:flex;justify-content:space-between;align-items:center"><span class="card-icon">${icon('book')}</span><span class="badge">${esc(c.level||'غير محدد')}</span></div><h3>${esc(c.name)}</h3><p>${icon('teacher')} ${esc(c.teacher_name||'غير محدد')}</p><p>${icon('clock')} ${esc(c.schedule||'لم يُحدّد الجدول')}</p><div class="card-meta"><span>${num(c.students_count)} طالبًا</span>${user.role==='admin'?`<button class="text-button" onclick="circleForm(${c.id})">إدارة الحلقة ←</button>`:''}</div></article>`).join('')}</div>${cs.length?'':empty('لا توجد حلقات ضمن نطاق حسابك')}`}
function circleForm(id){let c=id?window.circleRows.find(c=>c.id===id):{};formModal(id?'تعديل الحلقة':'إضافة حلقة قرآنية','تغيير معلم الحلقة ينقل صلاحية متابعة طلابها إلى المعلم الجديد تلقائيًا.',field('name','اسم الحلقة *','text',c.name,'required')+selectField('teacher_id','المعلم المسؤول *',options(meta.users.filter(u=>u.role==='teacher'),'id','name',c.teacher_id))+selectField('level','المستوى',options(['مبتدئ','متوسط','متقدم'].map(x=>({id:x,name:x})),'id','name',c.level))+field('schedule','جدول الدراسة','text',c.schedule),async d=>await api('/circles'+(id?'/'+id:''),id?'PUT':'POST',d));if(id)$('#editForm .form-actions').insertAdjacentHTML('afterbegin',`<button type="button" class="btn danger" onclick="deleteCircle(${id})">حذف الحلقة</button>`)}
async function deleteCircle(id){if(!confirm('حذف الحلقة؟ يجب نقل طلابها أولًا.'))return;await api('/circles/'+id,'DELETE');closeModal();toast('تم حذف الحلقة');meta=await api('/meta');await circlesPage()}
async function attendancePage(){studentList=await api('/students');$('#content').innerHTML=heading('الحضور والغياب','تسجيل يومي واضح؛ سجل واحد لكل طالب في كل يوم.',has('attendance')?btn('إضافة سجل حضور',"recordForm('attendance')"):'')+`<section class="panel"><div class="filter-bar"><input type="date" class="compact-input" id="attendanceDate" value="${meta.today}" max="${meta.today}" onchange="loadAttendance()" aria-label="تاريخ الحضور"><select id="attendanceCircle" onchange="loadAttendance()" aria-label="تصفية حسب الحلقة"><option value="">جميع الحلقات</option>${options(meta.circles)}</select><span class="filter-count" id="attendanceCount"></span>${has('attendance')?'<button class="btn small" onclick="markAllPresent()">تعيين غير المسجّل حاضرًا</button><button class="btn primary small" onclick="saveAllAttendance(this)">حفظ السجل اليومي</button>':''}</div><div id="attendanceTable"></div></section><p class="help">المتأخر يُحتسب حاضرًا في نسبة الحضور. السجلات غير المحفوظة لا تدخل في الإحصائيات.</p>`;await loadAttendance()}
async function loadAttendance(){let dt=$('#attendanceDate').value,ci=$('#attendanceCircle').value;if(!dt)return;let rec=await api('/records/attendance?start='+dt+'&end='+dt);let ss=studentList.filter(s=>(!ci||String(s.circle_id)===ci)&&(s.status==='active'||rec.some(r=>r.student_id===s.id)));$('#attendanceCount').textContent=num(ss.length)+' طالبًا';$('#attendanceTable').innerHTML=ss.length?table(['الطالب','الحلقة','الحالة','ملاحظة'],ss.map((s,i)=>{let r=rec.find(x=>x.student_id===s.id);return `<tr data-att-student="${s.id}"><td><span class="person">${avatar(s,i)}<span><strong>${esc(s.name)}</strong><small>${esc(s.code)}</small></span></span></td><td>${esc(s.circle_name||'—')}</td><td>${has('attendance')?`<select class="compact-input att-status" aria-label="حضور ${esc(s.name)}"><option value="">غير مسجّل</option>${options(['present','absent','late','excused'].map(id=>({id,name:statusNames[id]})),'id','name',r?.status)}</select>`:r?badge(r.status):'غير مسجّل'}</td><td>${has('attendance')?`<input class="compact-input att-note" aria-label="ملاحظة ${esc(s.name)}" placeholder="ملاحظة اختيارية" value="${esc(r?.note||'')}">`:esc(r?.note||'—')}</td></tr>`}).join('')):empty('لا يوجد طلاب في هذه الحلقة')}
function markAllPresent(){document.querySelectorAll('.att-status').forEach(n=>{if(!n.value)n.value='present'})}
async function saveAllAttendance(b){let rr=[...document.querySelectorAll('[data-att-student]')].filter(r=>r.querySelector('.att-status').value);if(!rr.length){toast('اختر حالة لطالب واحد على الأقل',true);return}b.disabled=true;let count=0;try{for(let r of rr){await api('/records/attendance','POST',{student_id:Number(r.dataset.attStudent),date:$('#attendanceDate').value,status:r.querySelector('.att-status').value,note:r.querySelector('.att-note').value});count++}toast(`تم حفظ ${num(count)} سجل حضور`)}catch(e){toast(`حُفظ ${count} سجل. ${e.message}`,true)}finally{b.disabled=false;await loadAttendance()}}
function recordTable(kind,rr,profile=false){if(!rr.length)return empty('لا توجد سجلات للفترة المحددة.');let heads=profile?['التاريخ']:['الطالب','التاريخ'];if(kind==='attendance')heads.push('الحالة','ملاحظات');else if(kind==='progress')heads.push('السورة / الجزء','الحفظ الجديد','المراجعة','الإتقان','الأخطاء / ملاحظات');else if(['monthly','quarterly'].includes(kind))heads.push('الفترة','الحفظ','المراجعة','التلاوة','الدرجة / التقدير','الأخطاء / ملاحظات');else if(kind==='charges')heads.push('المبلغ','الاستحقاق','البيان');else heads.push('المبلغ','البيان');heads.push('');return table(heads,rr.map(r=>{let td=x=>`<td>${x}</td>`,cells=(profile?'':td(`<a href="#profile/${r.student_id}"><strong>${esc(r.student_name)}</strong><small>${esc(r.code)}</small></a>`))+td(esc(r.date));if(kind==='attendance')cells+=td(badge(r.status))+td(esc(r.note||'—'));else if(kind==='progress')cells+=td(esc(r.surah)+`<small>الجزء ${num(r.juz)}</small>`)+td(esc(r.new_amount))+td(esc(r.review))+td(`<strong>${fmt(r.mastery)}%</strong><div class="progress-bar"><i style="width:${r.mastery}%"></i></div>`)+td(esc(r.errors||'—')+`<small>${esc(r.note)}</small>`);else if(['monthly','quarterly'].includes(kind))cells+=td(esc(r.period))+td(esc(r.memorization))+td(esc(r.review))+td(esc(r.recitation))+td(`<strong>${fmt(r.grade)} / 100</strong><small>${gradeName(r.grade)}</small>`)+td(esc(r.errors||'—')+`<small>${esc(r.note)}</small>`);else if(kind==='charges')cells+=td(money(r.amount))+td(esc(r.due_date))+td(esc(r.note));else cells+=td(money(r.amount))+td(esc(r.note));let perm=['charges','payments'].includes(kind)?'finance':kind;cells+=td(kind==='payments'?`<button class="text-button" onclick="receiptModal(${r.id})">${icon('print')} الإيصال</button>`:has(perm)&&kind!=='charges'?`<button class="icon-button" aria-label="تعديل السجل" onclick="editRecord('${kind}',${r.id},${r.student_id})">${icon('edit')}</button><button class="icon-button" aria-label="حذف السجل" onclick="deleteRecord('${kind}',${r.id})">${icon('trash')}</button>`:'');return '<tr>'+cells+'</tr>'}).join(''))}
async function recordsPage(kind){$('#content').innerHTML=heading(titles[kind],kind==='progress'?'كل متابعة تُظهر خطوة جديدة في رحلة الحفظ والإتقان.':kind==='monthly'?'اختبارات شهرية مستقلة تحفظ النتائج وتوضح التطور عبر الزمن.':'امتحانات كل ثلاثة أشهر، مع ملاحظات لجنة الامتحان والمقارنة بالاختبارات.',has(kind)?btn('إضافة '+(kind==='progress'?'متابعة':'نتيجة'),`recordForm('${kind}')`):'')+`<section class="panel"><div class="filter-bar"><input class="compact-input" type="date" id="recordStart" aria-label="من تاريخ" onchange="loadRecords('${kind}')"><span class="help">إلى</span><input class="compact-input" type="date" id="recordEnd" aria-label="إلى تاريخ" value="${meta.today}" onchange="loadRecords('${kind}')"><select id="recordCircle" onchange="loadRecords('${kind}')" aria-label="الحلقة"><option value="">جميع الحلقات</option>${options(meta.circles)}</select><button class="btn small" onclick="exportRecords('${kind}')">${icon('download')}تصدير CSV</button><span class="filter-count" id="recordCount"></span></div><div id="recordsTable"></div></section>`;await loadRecords(kind)}
async function loadRecords(kind){let q=new URLSearchParams({start:$('#recordStart').value||'1900-01-01',end:$('#recordEnd').value||meta.today,circle:$('#recordCircle').value});currentRecords=await api('/records/'+kind+'?'+q);$('#recordCount').textContent=num(currentRecords.length)+' سجلًا';$('#recordsTable').innerHTML=recordTable(kind,currentRecords)}
function exportRecords(kind){let keys=kind==='progress'?['date','student_name','surah','juz','new_amount','review','mastery','errors','note']:['date','student_name','period','memorization','review','recitation','grade','errors','note'];let labels=kind==='progress'?['التاريخ','الطالب','السورة','الجزء','الحفظ','المراجعة','الإتقان','الأخطاء','الملاحظات']:['التاريخ','الطالب','الفترة','الحفظ','المراجعة','التلاوة','الدرجة','الأخطاء','الملاحظات'];exportCSV(titles[kind],labels,currentRecords.map(r=>keys.map(k=>r[k])))}
async function editRecord(kind,id,sid){let data=await api('/students/'+sid);let r=data.records[kind]?.find(r=>r.id===id);if(!r)throw Error('السجل غير متاح');await recordForm(kind,sid,r)}
async function deleteRecord(kind,id){if(!confirm('حذف هذا السجل نهائيًا؟ سيُوثّق الحذف في سجل النشاط.'))return;await api('/records/'+kind+'/'+id,'DELETE');toast('تم حذف السجل');await refreshPage()}
async function recordForm(kind,sid,r={}){let ss=await api('/students');if(!ss.length){toast('أضف طالبًا أولًا أو اطلب إسناد طلاب إلى حسابك',true);return}let isFinance=['charges','payments'].includes(kind);let labels={attendance:'سجل حضور',progress:'متابعة حفظ ومراجعة',monthly:'نتيجة اختبار شهري',quarterly:'نتيجة امتحان دوري',charges:'رسوم مستحقة',payments:'دفعة مالية'};let fields=selectField('student_id','الطالب *',options(ss,'id','name',sid||r.student_id))+field('date','التاريخ *','date',r.date||meta.today,`required max="${meta.today}"`);if(kind==='attendance')fields+=selectField('status','الحالة',options(['present','absent','late','excused'].map(id=>({id,name:statusNames[id]})),'id','name',r.status));else if(kind==='progress'){fields+=field('surah','السورة *','text',r.surah,'required')+field('juz','الجزء *','number',r.juz||1,'required min="1" max="30"')+field('new_amount','مقدار الحفظ الجديد','text',r.new_amount,'placeholder="مثال: الآيات 1–10، وجه واحد"')+field('review','مقدار المراجعة','text',r.review)+field('mastery','مستوى الإتقان من 100 *','number',r.mastery??90,'required min="0" max="100" step="0.1"')+field('errors','الأخطاء','text',r.errors)}else if(['monthly','quarterly'].includes(kind)){fields+=field('period',kind==='monthly'?'الشهر / الفترة':'فترة الامتحان (ثلاثة أشهر)','text',r.period||meta.today.slice(0,7),'required')+field('grade','الدرجة النهائية من 100 *','number',r.grade??90,'required min="0" max="100" step="0.1"')+field('memorization','مقدار الحفظ المختبَر','text',r.memorization)+field('review','المراجعة','text',r.review)+field('recitation','التلاوة','text',r.recitation)+field('errors','الأخطاء','text',r.errors)}else{fields+=field('amount','المبلغ ('+currency()+') *','number',r.amount,'required min="0.01" max="10000000" step="0.01"');if(kind==='charges')fields+=field('due_date','تاريخ الاستحقاق *','date',r.due_date||meta.today,'required');}fields+=field('note',kind==='quarterly'?'ملاحظات لجنة الامتحان':isFinance?'البيان المالي':'ملاحظات المعلم','textarea',r.note,'maxlength="3000"',true);formModal((r.id?'تعديل ':'إضافة ')+labels[kind],isFinance?'يُسجّل المبلغ في قاعدة البيانات. القيود المالية المثبتة غير قابلة للحذف أو التعديل في هذه النسخة.':'تنعكس البيانات مباشرة في ملف الطالب وتقاريره وإحصائياته.',fields,async d=>{if(sid)d.student_id=sid;await api('/records/'+kind+(r.id?'/'+r.id:''),r.id?'PUT':'POST',d)});if(sid)$('#f-student_id').disabled=true;}
async function financePage(){let [d,ss,payments,charges]=await Promise.all([api('/dashboard'),api('/students'),api('/records/payments'),api('/records/charges')]);if(!d.finance)throw Error('ليست لديك صلاحية مالية');studentList=ss;window.financeRows={payments,charges};$('#content').innerHTML=heading('الرسوم والمدفوعات','مستحقات واضحة، ودفعات موثّقة، وأرقام مالية مترابطة.',canFinanceWrite()?btn('إثبات رسوم',"recordForm('charges')",'plus',false)+btn('تسجيل دفعة',"recordForm('payments')",'plus'):'')+`<div class="stats-grid">${stat('إجمالي المستحقات',d.finance.charged,'finance','',currency(),'finance')}${stat('إجمالي المحصّل',d.finance.paid,'check','blue',currency(),'finance')}${stat('المتبقي',d.finance.balance,'clock','gold',currency(),'finance')}${stat('المتأخرات',d.finance.overdue,'bell','purple',currency(),'finance')}</div><div class="tabs"><button class="tab active" onclick="financeTab('balances',this)">أرصدة الطلاب</button><button class="tab" onclick="financeTab('payments',this)">سجل المدفوعات</button><button class="tab" onclick="financeTab('charges',this)">الرسوم المستحقة</button></div><section class="panel"><div class="panel-head"><div><h3 id="financeTableTitle">الأرصدة المالية للطلاب</h3><p>تُخصم الدفعات من أقدم المستحقات في حساب إجمالي المتأخرات</p></div><button class="btn small" onclick="exportFinance()">${icon('download')}تصدير مالي</button></div><div id="financeTable"></div></section><div class="notice">العملة الحالية: ${currency()}. الرصيد السالب يُمثّل رصيدًا دائنًا للطالب. تقرير الفترة يُظهر التدفقات خلالها والأرصدة التراكمية حتى نهايتها.</div>`;financeTab('balances')}
function financeTab(tab,button){window.financeCurrent=tab;if(button){document.querySelectorAll('.tab').forEach(t=>t.classList.remove('active'));button.classList.add('active')}$('#financeTableTitle').textContent={balances:'الأرصدة المالية للطلاب',payments:'المدفوعات وإيصالات الدفع',charges:'الرسوم وتواريخ الاستحقاق'}[tab];$('#financeTable').innerHTML=tab==='balances'?table(['الطالب','المستحقات','المدفوع','المتبقي','المتأخرات',''],studentList.map(s=>`<tr><td><a href="#profile/${s.id}"><strong>${esc(s.name)}</strong><small>${esc(s.code)}</small></a></td><td>${money(s.finance.charged)}</td><td>${money(s.finance.paid)}</td><td>${money(s.finance.balance)}</td><td>${s.finance.overdue>0?`<span class="badge red">${money(s.finance.overdue)}</span>`:'—'}</td><td>${canFinanceWrite()?`<button class="btn small" onclick="recordForm('payments',${s.id})">تسجيل دفعة</button>`:`<button class="text-button" onclick="navigate('profile/${s.id}')">عرض الملف</button>`}</td></tr>`).join('')):recordTable(tab,window.financeRows[tab])}
function exportFinance(){exportCSV('الأرصدة-المالية',['الرقم','الطالب','المستحقات','المدفوع','المتبقي','المتأخرات','العملة'],studentList.map(s=>[s.code,s.name,s.finance.charged,s.finance.paid,s.finance.balance,s.finance.overdue,meta.settings.currency]))}
async function receiptModal(id){let r=await api('/receipts/'+id);openModal(`<div class="report-document"><div class="report-header">${brand}<div><h2 id="modalTitle">إيصال دفع</h2><p>رقم الإيصال: <b dir="ltr">PAY-${String(r.id).padStart(6,'0')}</b></p></div></div><div class="profile-info">${info('الطالب',r.name)+info('الرقم التعريفي',r.code)+info('تاريخ الدفع',r.date)+info('المبلغ المدفوع',fmt(r.amount)+' '+meta.settings.currency)+info('مُصدر الإيصال',r.author)+info('البيان',r.note)}</div><div class="report-summary">تم تسجيل المبلغ أعلاه في النظام. ${demoMode?'هذا الإيصال صادر عن النسخة التجريبية وليس مستندًا ماليًا للاستخدام الفعلي.':'يُعتمد الإيصال بعد توقيع المحاسب وختم المعهد.'}</div><div class="report-footer"><span>توقيع المحاسب: __________________</span><span>ختم المعهد: __________________</span></div></div><div class="form-actions no-print"><button class="btn" onclick="closeModal()">إغلاق</button><button class="btn primary" onclick="window.print()">${icon('print')}طباعة / حفظ PDF</button></div>`,true)}
function rangeFor(period){let end=new Date(meta.today+'T12:00:00'),start=new Date(end);if(period==='all')return {start:'1900-01-01',end:meta.today};start.setMonth(start.getMonth()-Number(period));return {start:start.toISOString().slice(0,10),end:meta.today}}
async function reportsPage(){studentList=await api('/students');$('#content').innerHTML=heading('التقارير والإحصائيات','حوّل السجلات اليومية إلى رؤية واضحة لمسيرة الطالب والمعهد.',btn('تصدير قائمة الطلاب','exportStudents()','download',false))+`<section class="panel"><div class="panel-head"><div><h3>التقرير الشامل للطالب</h3><p>بيانات الطالب وسجلات الفترة المحددة، مع أرصدة مالية حتى نهاية الفترة عند توفر الصلاحية.</p></div><span class="card-icon">${icon('reports')}</span></div><div class="filter-bar"><select id="reportStudent" style="min-width:220px;flex:1" aria-label="اختر الطالب">${options(studentList)}</select><select id="reportPeriod" aria-label="الفترة"><option value="1">آخر شهر</option><option value="3">آخر 3 أشهر</option><option value="6">آخر 6 أشهر</option><option value="12">آخر سنة</option><option value="all" selected>كامل المسيرة</option></select><button class="btn primary" onclick="reportModal(Number($('#reportStudent').value),$('#reportPeriod').value)">${icon('reports')}عرض التقرير</button></div></section><section class="panel" style="margin-top:23px"><div class="panel-head"><div><h3>الإحصائيات ضمن نطاق حسابك</h3><p>الفترة المختارة تُطبّق على متوسط النتائج والمدفوعات والأرصدة.</p></div><select class="compact-input" id="statsPeriod" onchange="loadReportStats()"><option value="1">آخر شهر</option><option value="3" selected>آخر 3 أشهر</option><option value="6">آخر 6 أشهر</option><option value="12">آخر سنة</option><option value="all">كامل المسيرة</option></select></div><div id="reportStats" style="padding:0 23px 23px"></div></section><div class="notice">التصدير إلى PDF يتم من نافذة الطباعة باختيار «حفظ بتنسيق PDF». يمكن حفظ نسخة ثابتة من التقرير في الأرشيف؛ تظهر في ملف الطالب ضمن «التقارير السابقة»، وتبقى خاضعة لصلاحيات الوصول الحالية.</div>`;await loadReportStats()}
async function loadReportStats(){let range=rangeFor($('#statsPeriod').value),d=await api('/dashboard?'+new URLSearchParams(range));$('#reportStats').innerHTML=`<div class="small-stats">${smallStat('إجمالي الطلاب',num(d.students))}${smallStat('طلاب نشطون حاليًا',num(d.active))}${user.role!=='accountant'?smallStat('متوسط الاختبارات',fmt(d.monthly_average)+'%')+smallStat('متوسط الامتحانات',fmt(d.quarterly_average)+'%'):smallStat('الحلقات',num(d.circles))+smallStat('المعلمون',num(d.teachers))}</div>${d.finance?`<div class="financial-grid">${financialMini('مدفوعات الفترة',d.finance.period_paid)}${financialMini('الرصيد حتى نهاية الفترة',d.finance.balance)}${financialMini('المتأخر حتى نهاية الفترة',d.finance.overdue)}</div>`:''}${d.trend?.length?`<h4 style="font-size:13px;font-weight:500">تطوّر متوسط نتائج الاختبارات الشهرية</h4>${table(['الشهر','متوسط الدرجة','التقدير'],d.trend.map(t=>`<tr><td>${t.month}</td><td><strong>${fmt(t.average)} / 100</strong><div class="progress-bar"><i style="width:${t.average}%"></i></div></td><td>${gradeName(t.average)}</td></tr>`).join(''))}`:''}<p class="help">أعداد الطلاب والحلقات تمثّل الوضع الحالي. مقارنات النتائج متوسطات للسجلات المتاحة، وليست قياسًا لحفظ أجزاء كاملة.</p>`}
async function reportModal(id,period='all',archiveId=null){if(!id){toast('اختر طالبًا أولًا',true);return}let archive=archiveId?await api('/report-archive/'+archiveId):null;let range=archive?{start:archive.start,end:archive.end}:rangeFor(period),d=archive?archive.data:await api('/reports/'+id+'?'+new URLSearchParams(range));window.currentReport={id,range};let s=d.student,r={attendance:[],progress:[],monthly:[],quarterly:[],...d.records},a=attendanceStats(r.attendance||[]),m=r.monthly||[],q=r.quarterly||[],p=r.progress||[],latest=m[0],oldest=m[m.length-1],delta=latest&&oldest?latest.grade-oldest.grade:0;let simpleRecords=(kind,head,keys)=>{let rr=r[kind]||[];return rr.length?table(head,rr.map(x=>'<tr>'+keys.map(k=>`<td>${esc(k==='amount'?fmt(x[k])+' '+meta.settings.currency:k==='status'?statusNames[x[k]]:x[k]??'—')}</td>`).join('')+'</tr>').join('')):'<p class="help">لا توجد سجلات في هذه الفترة.</p>'};let periodLabel=range.start==='1900-01-01'?'كامل مسيرة الطالب':range.start+' — '+range.end;openModal(`<div class="report-document"><div class="report-header">${brand}<div><h2 id="modalTitle">التقرير الشامل للطالب</h2><p>${esc(periodLabel)}<br>تاريخ الإصدار: ${archive?esc(archive.created_at.slice(0,10)):meta.today}${archive?'<br>نسخة محفوظة رقم '+archive.id:''}</p></div></div><div class="profile-info">${info('الاسم الكامل',s.name)+info('الرقم التعريفي',s.code)+info('تاريخ الميلاد',s.birth_date)+info('الحلقة',s.circle_name)+info('المعلم',s.teacher_name)+info('الوكيل',s.agent_name)+info('ولي الأمر',s.guardian)+info('الهاتف',s.guardian_phone||s.phone)+info('التسجيل / المستوى',s.registered+' / '+s.level)}</div>${user.role!=='accountant'?`<h3>ملخص المسيرة والتطور</h3><div class="report-summary">سُجّلت ${num(r.attendance.length)} متابعة حضور، بنسبة حضور ${a.rate}%. لدى الطالب ${num(p.length)} سجل حفظ ومراجعة، و${num(m.length)} اختبارات شهرية، و${num(q.length)} امتحانات دورية خلال الفترة.<br>${latest?`آخر نتيجة شهرية: ${fmt(latest.grade)} / 100 (${gradeName(latest.grade)}). `:''}${m.length>1?`التغير من أول اختبار إلى آخر اختبار في الفترة: ${delta>0?'+':''}${fmt(delta)} نقطة.`:'لا توجد اختبارات كافية لحساب تطور الدرجة.'}${q.length&&latest?`<br>مقارنة أحدث امتحان (${fmt(q[0].grade)}) بأحدث اختبار شهري (${fmt(latest.grade)}): ${fmt(q[0].grade-latest.grade)} نقطة. للمقارنة الاسترشادية فقط؛ قد يختلف مقدار الحفظ المختبَر.`:''}</div><h3>الحضور والغياب</h3><p class="help">حاضر: ${num(a.present)} · غائب: ${num(a.absent)} · متأخر: ${num(a.late)} · بعذر: ${num(a.excused)}. النسبة تشمل الحاضر والمتأخر من جميع الأيام المسجلة.</p>${simpleRecords('attendance',['التاريخ','الحالة','الملاحظات'],['date','status','note'])}<h3>الحفظ والمراجعة والإتقان</h3>${simpleRecords('progress',['التاريخ','السورة','الجزء','الحفظ الجديد','المراجعة','الإتقان %','الأخطاء','ملاحظات المعلم'],['date','surah','juz','new_amount','review','mastery','errors','note'])}<h3>الاختبارات الشهرية</h3>${simpleRecords('monthly',['التاريخ','الفترة','الحفظ','المراجعة','التلاوة','الدرجة /100','الأخطاء','الملاحظات'],['date','period','memorization','review','recitation','grade','errors','note'])}<h3>الامتحانات كل ثلاثة أشهر</h3>${simpleRecords('quarterly',['التاريخ','الفترة','الحفظ','المراجعة','التلاوة','الدرجة /100','ملاحظات اللجنة'],['date','period','memorization','review','recitation','grade','note'])}<p class="help">التقدير: 90 فأعلى ممتاز · 80 فأعلى جيد جدًا · 70 فأعلى جيد · 60 فأعلى مقبول · أقل من 60 يحتاج إلى دعم.</p><h3>ملاحظات الإدارة</h3><p>${esc(s.notes||'لا توجد ملاحظات إدارية.')}</p>`:''}${d.finance?`<h3>الملخص المالي</h3><div class="report-summary">حتى نهاية الفترة: المستحقات ${fmt(d.finance.charged)} ${currency()} · المدفوع ${fmt(d.finance.paid)} ${currency()} · المتبقي ${fmt(d.finance.balance)} ${currency()} · المتأخر ${fmt(d.finance.overdue)} ${currency()}.<br>مدفوعات الفترة المحددة: ${fmt(d.finance.period_paid)} ${currency()}.</div><h3>مستحقات الفترة</h3>${simpleRecords('charges',['التاريخ','الاستحقاق','المبلغ','البيان'],['date','due_date','amount','note'])}<h3>مدفوعات الفترة</h3>${simpleRecords('payments',['التاريخ','المبلغ','البيان'],['date','amount','note'])}`:''}<div class="report-footer"><span>أعدّه: ${esc(user.name)} · ${roleNames[user.role]}</span><span>${demoMode?'بيانات تجريبية · للاختبار فقط':'تقرير صادر من نظام المعهد'}</span></div></div><div class="form-actions no-print"><button class="btn" onclick="closeModal()">إغلاق</button>${!archive?`<button class="btn" onclick="saveReportArchive(this)">${icon('reports')}حفظ نسخة في الأرشيف</button>`:''}<button class="btn primary" onclick="window.print()">${icon('print')}طباعة / تصدير PDF</button></div>`,true)}
async function notificationsPage(){let nn=await api('/notifications');$('#content').innerHTML=heading('التنبيهات','أحداث تخص طلابك، ومواعيد قادمة، ومستحقات تحتاج إلى متابعة.',btn('تحديث','notificationsPage()','bell',false))+`<section class="panel">${nn.map(n=>`<div class="notification-row"><span class="card-icon">${icon({absence:'attendance',update:'progress',exam:'calendar',fee:'finance'}[n.type])}</span><div><h4>${esc(n.title)}</h4><small>${esc(n.date)} ${n.amount?' · '+fmt(n.amount)+' '+currency():''}</small></div>${n.student_id?`<button class="btn small" onclick="navigate('profile/${n.student_id}')">عرض الطالب ←</button>`:`<button class="btn small" onclick="navigate('schedules')">عرض الموعد</button>`}</div>`).join('')||empty('لا توجد تنبيهات حاليًا')}</section><p class="help">تنبيهات داخل النظام تُولّد من البيانات عند فتح الصفحة؛ لا تُرسل رسائل SMS أو بريدًا إلكترونيًا.</p>`}
async function schedulesPage(){let rr=await api('/schedules');$('#content').innerHTML=heading('المواعيد القادمة','جدولة الاختبارات الشهرية والامتحانات الدورية كل ثلاثة أشهر.',user.role==='admin'?btn('إضافة موعد','scheduleForm()'):'')+`<section class="panel">${table(['الموعد','النوع','التاريخ','الحلقة','الحالة',''],rr.map(r=>`<tr><td><strong>${esc(r.title)}</strong></td><td>${r.type==='monthly'?'اختبار شهري':'امتحان دوري'}</td><td>${esc(r.date)}</td><td>${esc(r.circle_name||'جميع الحلقات')}</td><td><span class="badge ${r.date<meta.today?'gray':''}">${r.date<meta.today?'موعد سابق':'قادم'}</span></td><td>${user.role==='admin'?`<button class="icon-button" onclick="deleteSchedule(${r.id})" aria-label="حذف الموعد">${icon('trash')}</button>`:''}</td></tr>`).join(''))}</section><p class="help">المواعيد مستقلة عن إدخال النتائج. كل امتحان يُجدول يدويًا بتاريخ الدورة المطلوبة.</p>`}
function scheduleForm(){formModal('إضافة موعد اختبار أو امتحان','سيظهر الموعد في لوحة التحكم والتنبيهات للحسابات المعنية.',field('title','اسم الموعد *','text','','required')+selectField('type','النوع','<option value="monthly">اختبار شهري</option><option value="quarterly">امتحان دوري (3 أشهر)</option>')+field('date','التاريخ *','date',meta.today,'required')+selectField('circle_id','الحلقة','<option value="">جميع الحلقات</option>'+options(meta.circles)),async d=>await api('/schedules','POST',d))}
async function deleteSchedule(id){if(!confirm('حذف هذا الموعد؟'))return;await api('/schedules/'+id,'DELETE');toast('تم حذف الموعد');await schedulesPage()}
async function settingsPage(){let s=await api('/settings');$('#content').innerHTML=heading('إعدادات المعهد','إعدادات الهوية والعملة، مع الحفاظ على ترابط السجلات.')+`<section class="panel settings-panel"><h3>البيانات الأساسية</h3><p class="help">الرسوم مرنة: يُحدّد المدير المبلغ وتاريخ الاستحقاق لكل قيد. لا تُنشأ رسوم شهرية تلقائيًا.</p><form id="settingsForm"><div class="form-grid" style="margin-top:25px">${field('institute','اسم المعهد *','text',s.institute,'required',true)}${field('currency','رمز العملة أو اسمها *','text',s.currency,'required maxlength="12"',true)}</div><div class="notice">تغيير العملة يغيّر تسمية المبالغ القديمة والجديدة فقط، ولا يُجري تحويلًا ماليًا. حدّد العملة النهائية قبل إدخال البيانات الحقيقية.</div><label class="inline-check"><input type="checkbox" name="confirm_currency">أفهم أثر تغيير تسمية العملة على السجلات السابقة.</label><div class="form-actions"><button type="submit" class="btn primary">${icon('check')}حفظ الإعدادات</button></div></form></section><section class="panel settings-panel" style="margin-top:22px"><h3>النسخ الاحتياطي والاستعادة</h3><p class="help">نزّل نسخة كاملة من قاعدة البيانات (الطلاب والحضور والحفظ والنتائج والرسوم) واحتفظ بها في مكان آمن. عند الحاجة، ارفع النسخة للاستعادة — تُحفظ نسخة «قبل الاستعادة» تلقائيًا.</p><div style="display:flex;gap:10px;flex-wrap:wrap;margin-top:12px"><button class="btn" onclick="downloadBackup()">${icon('download')}تنزيل نسخة احتياطية</button><label class="btn" style="cursor:pointer">${icon('reports')}استعادة من نسخة<input type="file" accept=".sqlite3" hidden onchange="restoreBackup(this)"></label></div></section><section class="panel settings-panel" style="margin-top:22px"><h3>البدء بالعمل الفعلي</h3><p class="help">عند أول استخدام حقيقي: يُحذف جميع الطلاب والحلقات والسجلات التجريبية نهائيًا، وتُخفى حسابات التجربة من صفحة الدخول. لا يمكن التراجع — نزّل نسخة احتياطية قبلها إن أردت الاحتفاظ بالتجربة.</p><button class="btn danger" style="margin-top:10px" onclick="demoReset()">${icon('trash')}مسح البيانات التجريبية وبدء العمل الفعلي</button></section><section class="panel settings-panel" style="margin-top:22px"><h3>الأمان والجاهزية للنشر</h3><p class="help">قاعدة بيانات SQLite حقيقية، وكلمات مرور مجزّأة، وجلسات دخول، وحماية CSRF، وتحقق من نطاق الطلاب في الخادم.</p><div class="notice">هذه بيئة معاينة وليست استضافة إنتاجية. قبل العمل الفعلي: غيّر جميع الحسابات التجريبية، فعّل HTTPS وملفات تعريف الارتباط الآمنة، استخدم خادم WSGI، وجهّز النسخ الاحتياطي واستعادة البيانات ومراقبة التشغيل.</div><button class="btn" onclick="accountModal()">${icon('lock')}تغيير كلمة مرور حسابي</button></section>`;$('#settingsForm').onsubmit=async e=>{e.preventDefault();let d=Object.fromEntries(new FormData(e.target));await api('/settings','PUT',d);meta=await api('/meta');toast('تم تحديث الإعدادات')}}
function accountModal(){formModal('حسابي وكلمة المرور',esc(user.name)+' · '+roleNames[user.role],field('old','كلمة المرور الحالية *','password','','required autocomplete="current-password"',true)+field('new','كلمة المرور الجديدة *','password','','required minlength="10" autocomplete="new-password"',true),async d=>await api('/password','POST',d))}
(async()=>{try{demoMode=(await api('/public-config')).demo;let s=await api('/session');if(s.user){user=s.user;csrf=s.csrf;token=token||store.get('qalun_token')||'';await boot()}else showLogin()}catch(e){showLogin();toast(e.message,true)}})();

async function saveReportArchive(button){button.disabled=true;try{let d=await api('/report-archive?'+new URLSearchParams(window.currentReport.range),'POST',{student_id:window.currentReport.id});toast('حُفظت نسخة التقرير في الأرشيف · '+d.id);button.textContent='تم الحفظ في الأرشيف'}catch(e){button.disabled=false;throw e}}
async function loadArchives(sid){let rr=await api('/report-archive?student='+sid);if(!$('#archiveList'))return;$('#archiveList').innerHTML=rr.length?table(['رقم التقرير','تاريخ الحفظ','الفترة','أعدّه',''],rr.map(r=>`<tr><td>#${r.id}</td><td>${esc(r.created_at.replace('T',' · '))}</td><td>${r.start==='1900-01-01'?'كامل المسيرة حتى '+r.end:r.start+' — '+r.end}</td><td>${esc(r.author)}</td><td><button class="btn small" onclick="reportModal(${sid},'all',${r.id})">عرض / طباعة</button></td></tr>`).join('')):empty('لم تُحفظ تقارير سابقة. افتح التقرير الشامل ثم اختر «حفظ نسخة في الأرشيف».')}

async function downloadBackup(){try{let r=await fetch('/api/backup',{headers:{'X-Auth-Token':token}});if(!r.ok){let d=await r.json().catch(()=>({}));throw Error(d.error||'تعذّر تنزيل النسخة')}let blob=await r.blob();let a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='qalun-backup.sqlite3';document.body.appendChild(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(a.href),5000);toast('بدأ تنزيل النسخة الاحتياطية')}catch(e){toast(e.message,true)}}
function restoreBackup(input){let f=input.files[0];if(!f)return;if(!confirm('استعادة هذه النسخة ستستبدل جميع البيانات الحالية. متابعة؟')){input.value='';return}if(!confirm('تأكيد أخير: سيتم استبدال كل البيانات الحالية بالنسخة المرفوعة.')){input.value='';return}let fd=new FormData();fd.append('file',f);fetch('/api/restore',{method:'POST',headers:{'X-Auth-Token':token,'X-CSRF-Token':csrf||store.get('qalun_csrf')||''},body:fd}).then(async r=>{let d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.error||'فشلت الاستعادة');toast('تمت الاستعادة بنجاح');setTimeout(()=>location.reload(),800)}).catch(e=>toast(e.message,true));input.value=''}
function demoReset(){if(!confirm('سيتم حذف جميع الطلاب والحلقات والسجلات التجريبية نهائيًا. هل أنت متأكد؟'))return;if(!confirm('تأكيد نهائي: لا يمكن التراجع عن هذا الإجراء.'))return;api('/demo-reset','POST',{}).then(()=>{toast('تم التمهيد للعمل الفعلي');setTimeout(()=>location.reload(),700)}).catch(e=>toast(e.message,true))}

function importTemplate(){const rows=[['الاسم الكامل','تاريخ الميلاد','رقم الهاتف','اسم ولي الأمر','هاتف ولي الأمر','الحلقة','الوكيل','المستوى','الحالة'],['محمد أحمد','2010-05-12','97123456','أحمد محمد','','حلقة الإمام نافع','عبد الله المختار','متوسط',''],['فاطمة محمد','2011-02-03','','فاطمة إبراهيم','','حلقة البراعم','','مبتدئ','']];const csv='\uFEFF'+rows.map(r=>r.map(x=>'"'+String(x).replace(/"/g,'""')+'"').join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='قالب-استيراد-الطلاب.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),5000)}
function importModal(){openModal(`<h2 id="modalTitle">استيراد مجموعة من الطلاب</h2><p class="modal-description">ارفع ملف CSV يحتوي على صفوف الطلاب (يُصدَّر من Excel أو Google Sheets). يُسند رقم تعريفي تلقائيًا لكل طالب، وتظهر الأخطاء الصفّية إن وُجدت.</p><div class="notice"><b>الأعمدة:</b> الاسم الكامل (إجباري) · تاريخ الميلاد · رقم الهاتف · اسم ولي الأمر · هاتف ولي الأمر · الحلقة (باسم الحلقة الموجود) · الوكيل (باسم الوكيل) · المستوى (مبتدئ/متوسط/متقدم) · الحالة (نشط/موقوف/متخرج).<br><b>ملاحظة:</b> أسماء الحلقات والوكلاء يجب أن تطابق الموجودة في النظام تمامًا.</div><div style="display:flex;gap:10px;flex-wrap:wrap;margin-bottom:16px"><button type="button" class="btn" onclick="importTemplate()">${''}تنزيل القالب النموذجي</button></div><form id="importForm" onsubmit="submitImport(event)"><div class="field"><input type="file" id="importFile" name="file" accept=".csv,text/csv" required style="padding:11px;font-size:11px"></div><div id="importError"></div><div class="form-actions"><button type="button" class="btn" onclick="closeModal()">إلغاء</button><button type="submit" class="btn primary" id="importSubmit">ابدأ الاستيراد</button></div></form>`)}
async function submitImport(e){e.preventDefault();const f=$('#importFile').files[0];if(!f){$('#importError').innerHTML='<div class="form-error">اختر ملف CSV أولًا</div>';return}const b=$('#importSubmit');b.disabled=true;b.textContent='جارٍ الاستيراد…';$('#importError').innerHTML='';try{const fd=new FormData();fd.append('file',f);const r=await fetch('/api/students/import',{method:'POST',headers:{'X-Auth-Token':token,'X-CSRF-Token':csrf||store.get('qalun_csrf')||''},body:fd});const d=await r.json().catch(()=>({}));if(!r.ok)throw Error(d.error||'فشل الاستيراد');const errRows=(d.errors||[]).map(x=>`<li><b>صف ${x.row}:</b> ${esc(x.message)}</li>`).join('');$('#modalBody').innerHTML=`<div class="success" style="text-align:right"><div class="success-icon" style="margin:0 0 18px">✓</div><h2 id="modalTitle">اكتمل الاستيراد</h2><p>تمت إضافة <b>${d.added}</b> طالبًا بنجاح.</p>${errRows?`<p style="margin-top:14px;color:#b0745f"><b>${errRows.length}</b> صف غير مستورد:</p><ul style="text-align:right;padding-right:20px;font-size:12px;line-height:2">${errRows}</ul><p class="help">أصلح الصفوف المرفوضة في الملف وأعد رفعها (الصفوف الناجحة لن تُكرر).</p>`:''}<div class="form-actions" style="justify-content:center"><button class="btn" onclick="closeModal();navigate('students')">عرض قائمة الطلاب</button></div></div>`}catch(err){$('#importError').innerHTML=`<div class="form-error">${esc(err.message)}</div>`}finally{b.disabled=false;b.textContent='ابدأ الاستيراد'}}
